", \"00100\", \"00100\", \"11111\"],\n      \" \": [\"000\", \"000\", \"000\", \"000\", \"000\", \"000\", \"000\"]\n    };\n    var text = \"DUNE ENGINE\", P = 4, gap = 1;\n    var tc = document.getElementById(\"titleCv\"), tctx = tc.getContext(\"2d\");\n    var cols = 0; for (var i = 0; i < text.length; i++) cols += G[text[i]][0].length + gap;\n    cols -= gap;\n    tc.width = cols * P; tc.height = 7 * P + 12;\n    tc.style.width = \"auto\";\n    var grains = [], xo = 0;\n    for (var c = 0; c < text.length; c++){\n      var g = G[text[c]];\n      for (var r = 0; r < 7; r++) for (var q = 0; q < g[r].length; q++){\n        if (g[r][q] === \"1\"){\n          var col = PAL[SAND][(Math.random() * 4) | 0];\n          if (text[c] !== \" \" && c > 4) col = r < 2 ? \"#e0612a\" : (Math.random() < 0.5 ? \"#c1440e\" : \"#d4521a\");\n          grains.push({x: (xo + q) * P, ty: r * P + 12, y: -P * (4 + Math.random() * 14) - (xo + q) * 0.8, v: 0, col: col, done: false});\n        }\n      }\n      xo += g[0].length + gap;\n    }\n    var tStart = 0;\n    function drawTitle(ts){\n      if (!tStart) tStart = ts;\n      tctx.clearRect(0, 0, tc.width, tc.height);\n      var all = true;\n      grains.forEach(function(p){\n        if (!p.done){\n          if (reduced){ p.y = p.ty; p.done = true; }\n          else { p.v += 0.55; p.y += p.v; if (p.y >= p.ty){ p.y = p.ty; if (p.v > 2.5){ p.v = -p.v * 0.28; } else { p.done = true; } } all = false; }\n        }\n        tctx.fillStyle = p.col;\n        tctx.fillRect(p.x, Math.round(p.y), P - 0.5, P - 0.5);\n      });\n      if (!all) requestAnimationFrame(drawTitle);\n    }\n    requestAnimationFrame(drawTitle);\n  })();\n\n  /* ================= loop ================= */\n  var last = performance.now(), fpsT = last, fpsN = 0, rCount = document.getElementById(\"rCount\"), rFps = document.getElementById(\"rFps\");\n  function loop(ts){\n    requestAnimationFrame(loop);\n    if (document.hidden) return;\n    if (!paused){\n      speedAcc += SPEEDS[speedIdx];\n      while (speedAcc >= 1){\n        speedAcc -= 1;\n        if (ptr.down) paintAt(ptr.cx, ptr.cy, ptr.erase);\n        step();\n      }\n    } else if (ptr.down){ paintAt(ptr.cx, ptr.cy, ptr.erase); }\n    if (wipe >= 0){\n      var rows = Math.max(2, Math.ceil(H / 22));\n      for (var y = wipe; y < Math.min(H, wipe + rows); y++){ var row = y * W; for (var x = 0; x < W; x++){ type[row + x] = EMPTY; life[row + x] = 0; } }\n      wipe += rows; if (wipe >= H) wipe = -1;\n    }\n    render();\n    fpsN++;\n    if (ts - fpsT >= 500){\n      rFps.textContent = Math.round(fpsN * 1000 / (ts - fpsT));\n      rCount.textContent = count.toLocaleString(\"en-US\");\n      fpsN = 0; fpsT = ts;\n    }\n  }\n\n  var rzT = 0;\n  window.addEventListener(\"resize\", function(){ clearTimeout(rzT); rzT = setTimeout(function(){ fit(); render(); }, 80); });\n\n  fit();\n  var savedKey = null, savedBrush = null;\n  try { savedKey = localStorage.getItem(\"dune-tool\"); savedBrush = localStorage.getItem(\"dune-brush\"); } catch (e){}\n  pickTool(TOOLS.filter(function(x){ return x.key === savedKey; })[0] || TOOLS[0]);\n  setBrush(savedBrush ? +savedBrush : 5);\n  SCENES.volcano();\n  // let the scene settle for a moment so the first frame is already alive\n  for (var w0 = 0; w0 < 40; w0++) step();\n  render();\n  requestAnimationFrame(loop);\n})();\n</script>\n</body>\n</html>\n";
